INSERT OR REPLACE INTO course_syllabuses (level, title, description, modules_json, updated_at) VALUES
('A1', 'A1 入门基础完整课程', '面向零基础到入门阶段，围绕发音、日常沟通、基础语法和高频生活场景建立英语开口能力。', '[{"title":"第1单元 发音与课堂英语","goal":"熟悉英语字母、基础发音和课堂常用指令，能听懂简单学习场景表达。","lessons":["26个字母与常见字母组合发音","数字0-100、日期和时间读法","课堂指令：listen、repeat、write、ask"]},{"title":"第2单元 自我介绍","goal":"能介绍姓名、国家、职业和基本身份信息，并向他人提问。","lessons":["主语代词 I / you / he / she / we / they","be 动词肯定句、否定句和疑问句","写一段3-5句的自我介绍"]},{"title":"第3单元 人与物","goal":"能描述身边的人和物，表达所有关系和简单特征。","lessons":["this / that / these / those","a / an / the 与名词单复数","形容词描述：big、small、new、old、nice"]},{"title":"第4单元 家庭与朋友","goal":"能介绍家庭成员、朋友关系和基础外貌性格。","lessons":["have / has 表达拥有","家庭成员和关系词汇","用 and / but 连接两个简单句"]},{"title":"第5单元 日常生活","goal":"能谈论每天做什么、什么时候做，以及简单频率。","lessons":["一般现在时肯定句和否定句","时间、星期和频率副词 always / usually / sometimes","描述自己普通的一天"]},{"title":"第6单元 食物与购物","goal":"能点餐、询问价格、表达喜欢和数量需求。","lessons":["可数名词与不可数名词","some / any / much / many 基础用法","点餐和购物对话：I would like... / How much is it?"]},{"title":"第7单元 地点与问路","goal":"能说明位置、询问路线，并描述城市里的常见地点。","lessons":["there is / there are","介词 in / on / under / next to / between","问路表达：Where is...? / Go straight / Turn left"]},{"title":"第8单元 能力与请求","goal":"能表达会做什么、不会做什么，并提出礼貌请求。","lessons":["can / cannot 表达能力","Can I...? / Can you...? 礼貌请求","电话、预约和简单求助表达"]},{"title":"第9单元 过去的事情","goal":"能用简单过去时描述昨天、周末或一次短经历。","lessons":["一般过去时 was / were","规则动词过去式 -ed 与常见不规则动词","写一段5句左右的周末记录"]},{"title":"第10单元 A1综合任务","goal":"整合A1核心能力，完成真实生活中的短对话和短写作。","lessons":["自我介绍 + 日常安排综合口语","购物、问路、预约三类情景对话","完成一篇60词以内的A1个人短文"]}]', '2026-04-27T00:00:00.000Z');
